import numpy as np
from scipy.optimize import brentq

def solve(a, y, left, right):
    def f(x):
        return x + a * np.sin(x) - y

    x_root = brentq(f, left, right)
    dx_dy = 1.0 / (1.0 + a * np.cos(x_root))

    return np.array([x_root, dx_dy], dtype=np.float64)
