import numpy as np
from scipy.optimize import minimize

def solve(b, mass):
    b = np.asanyarray(b, dtype=np.float64)
    n = b.shape[0]

    def objective(x):
        return 0.5 * np.sum((x - b)**2)

    def gradient(x):
        return x - b

    cons = ({
        'type': 'eq',
        'fun': lambda x: np.sum(x) - mass,
        'jac': lambda x: np.ones_like(x)
    })

    bounds = [(0, None) for _ in range(n)]

    # Initial guess: distribute mass evenly
    x0 = np.full(n, mass / n, dtype=np.float64)

    res = minimize(
        fun=objective,
        x0=x0,
        jac=gradient,
        method='SLSQP',
        bounds=bounds,
        constraints=cons,
        options={'ftol': 1e-12}
    )

    return res.x.astype(np.float64)
```

