import numpy as np
from scipy.optimize import least_squares

def solve(t, y, weight):
    t = np.asarray(t)
    y = np.asarray(y)
    weight = np.asarray(weight)

    def fun(params, t, y, weight):
        slope, intercept = params
        return np.sqrt(weight) * (slope * t + intercept - y)

    def jac(params, t, y, weight):
        sqrt_w = np.sqrt(weight)
        return np.column_stack([sqrt_w * t, sqrt_w])

    x0 = np.array([0.0, 0.0])
    res = least_squares(fun, x0, jac=jac, args=(t, y, weight))
    return res.x.astype(np.float64)
```

