import numpy as np

def helper(nodes, weights, density):
    mass = weights * density
    return mass / mass.sum()

def solve(nodes, weights, density):
    p = helper(nodes, weights, density)
    mean = np.sum(p * nodes)
    variance = np.sum(p * (nodes - mean)**2)
    return np.array([mean, variance], dtype=np.float64)
```

