import numpy as np
from scipy.special import logsumexp

def helper(log_prior, log_likelihood):
    z = log_prior + log_likelihood
    return np.exp(z - logsumexp(z))

def solve(log_prior, log_likelihood, score):
    posterior = helper(log_prior, log_likelihood)
    return np.dot(posterior, score).astype(np.float64)
